stylesheet:
/* Hoja de estilos dinámica generada por ThemeEngine de Escritorio */
QMainWindow, QWidget#root {
    background-color: #EEE8D5;
    color: #657B83;
    font-family: 'Segoe UI Variable Display', 'Segoe UI', -apple-system, sans-serif;
    font-size: 11px;
}

/* Barra de herramientas compacta (28px) */
QToolBar#mainToolbar {
    background-color: #E8E2CF;
    color: #586E75;
    border-bottom: 1px solid #DACFB7;
    min-height: 28px;
    max-height: 28px;
    padding: 0 4px;
}
QToolBar#mainToolbar QToolButton {
    font-size: 10px;
    height: 22px;
    padding: 2px 6px;
    border-radius: 3px;
}
QToolBar#mainToolbar QToolButton:hover {
    background-color: #DFD7C2;
}

/* Binder / Navegador jerárquico */
QTreeView#binder {
    background-color: #EEE8D5;
    color: #657B83;
    border: none;
    border-right: 1px solid #DACFB7;
    font-size: 11px;
}
QTreeView#binder::item {
    height: 22px;
}
QTreeView#binder::item:selected {
    background-color: #DFD7C2;
    color: #073642;
    border-radius: 3px;
}

/* Cabecera del Editor (24px) */
QWidget#editorHeader {
    background-color: #F5EED9;
    color: #586E75;
    min-height: 24px;
    max-height: 24px;
    border-bottom: 1px solid #E0D9C4;
    font-size: 10px;
}

/* Editor RTF */
QTextEdit#editor {
    background-color: #FDF6E3;
    color: #657B83;
    selection-background-color: #EEE8D5;
    border: none;
    font-family: 'Georgia', 'Segoe UI Variable Text', serif;
}

/* Pizarra de Corcho (Corkboard) */
QWidget#corkboard {
    background-color: #E5DECB;
}
QWidget#corkboardCard {
    background-color: #FDF6E3;
    color: #657B83;
    border: 1px solid #DACFB7;
    border-radius: 4px;
}

/* Esquematizador (Outliner) */
QTableView#outliner {
    background-color: #FDF6E3;
    color: #657B83;
    gridline-color: #EEE8D5;
    border: none;
}
QTableView#outliner::item:alternate {
    background-color: #F8F0DC;
}

/* Inspector Lateral */
QDockWidget#inspector {
    background-color: #EEE8D5;
    color: #657B83;
    border-left: 1px solid #E0D9C4;
}
QWidget#inspectorCard {
    background-color: #FDF6E3;
    border: 1px solid #E0D9C4;
    border-radius: 4px;
}

/* Barra de estado */
QStatusBar#statusBar {
    background-color: #E8E2CF;
    color: #839496;
    border-top: 1px solid #DACFB7;
    min-height: 22px;
    font-size: 10px;
}

/* Micro-etiquetas y badges */
QLabel.microBadge {
    font-size: 9px;
    font-weight: bold;
    padding: 1px 4px;
    border-radius: 5px;
    background-color: #DFD7C2;
    color: #268BD2;
}
